INSERT INTO public.wf_doc VALUES (10, '预算花不完 · 发送', 'send', '预算', 1, NULL, 'station', NULL, 1, '{"who": "所级 → 该所所长：find_user(unit = 所名，如 厉山；role = 所长)\n县级 → 县公司财务部：find_user(unit = 县名，如 随县；role = 财务)\n市级 → 市公司领导：find_user(unit = 随州市；role = 市公司领导)\n\n查到多个取第一个；查不到这一层就不发，在 finish 的 note 里写清哪个单位缺哪个岗位。", "goal": "把《预算花不完》今天判出来的结果，按所、县、市三层各写成一句话，发给对应的人。\n产出：每人一条通知；覆盖了哪几条结果，记在这条通知里。", "rule": "四条都成立才发：status = open、reliable = true、tier 是 high 或 mid、last_seen 是今天。\n所级：按 unit_name 分组，每个所一句（组里多条就数条数）；\n县级：按 county_name 分组，每个县一句；\n市级：全部合成一句。", "fields": "object_name 对象名、unit_name 归属所、county_name 归属县、tier 档位（high / mid / low）、value 当前值配 value_unit 读（% 表示百分数）、reliable 数据是否可靠（0 不发）、status 问题还在不在。", "phrase": "不超过 30 字，只放一个数字。\n\n所级：{所名}今年预算只能花到 {整数}%\n县级：本县 {n} 所预算到年底花不完\n市级：全市 {n} 所预算到年底花不完\n\n不要写：样本总数、阈值、档位英文（high / mid）、一串明细。\n例：厉山供电所今年预算只能花到 42%", "source": "结果表，按文档名读：doc_name = 预算花不完；只要 status=open、last_seen 是今天。\n要用到的列：object_name 对象名、unit_name 归属所、county_name 归属县、tier 档位、value 当前值、value_unit 单位。\n最多 200 条，超过就翻页接着读，读完为止。", "delivery": "用 send 工具，一层一句话调一次：\nitem_ids 这几条结果的 id（第一个当成最差那条）\nlevel station / county / city\nscope_name 所名 或 县名 或 全市\nrecipient_login 查到的登录名；message 第五节的句子；reason 写为什么发他\n\n三层发完调 finish，sent_n 填实际发出条数。"}', 6, 'seed', '2026-11-07 11:15:53.993184+08', '2026-11-07 11:26:24.269318+08', 0) ON CONFLICT DO NOTHING;
INSERT INTO public.wf_doc VALUES (9, '审批长期未通过', 'detect', '审批', 1, NULL, 'station', NULL, NULL, '{"calc": "天数 = update_time 到今天的天数（没有审批任务表，只能用最后更新时间近似，是下限）。", "data": "t_power_ai_work_order：id、work_code、work_name、power_company_name、county_company_name、is_approved（0=未通过）、current_node_name 当前审批节点、update_time 最后更新时间、create_time、total_budget（元）、year、deleted_flag。\n只取：year=今年、deleted_flag=0、is_approved=0。", "goal": "查出哪张工单卡在审批里很久没通过，一张工单一条结果。\n产出：结果为未通过、最后更新超过 30 天的工单，带停留天数与当前节点。", "what": "哪张工单卡在审批里很久没通过。\n算到工单，一张一条。", "judge": "天数 > 30 报；> 90 为高档，其余中档。", "store": "对象：工单名（带所名）；对象键：工单 id。\n归属所：power_company_name；归属县：county_company_name。\n当前值：停留天数，单位 天。\n阈值 30，档位 high / mid。\n明细四项：当前节点、工单号、预算金额、天数按最后更新时间估算的说明。\n依据三项：审批状态、当前节点、最后更新时间。\n可靠性：update_time 为空的跳过，并在运行记录里注明。"}', 6, 'seed', '2026-11-07 11:15:53.990381+08', '2026-11-07 11:26:24.269318+08', 0) ON CONFLICT DO NOTHING;
INSERT INTO public.wf_doc VALUES (13, '台区线损超线 · 发送', 'send', '指标', 1, NULL, 'station', NULL, 4, '{"who": "所级 → 该所所长：find_user(unit = 所名，如 厉山；role = 所长)\n县级 → 县公司运检部：find_user(unit = 县名，如 随县；role = 运检)\n市级 → 市公司领导：find_user(unit = 随州市；role = 市公司领导)\n\n查到多个取第一个；查不到这一层就不发，在 finish 的 note 里写清哪个单位缺哪个岗位。", "goal": "把《台区线损超线》今天判出来的结果，按所、县、市三层各写成一句话，发给对应的人。\n产出：每人一条通知；覆盖了哪几条结果，记在这条通知里。", "rule": "四条都成立才发：status = open、reliable = true、tier 是 high 或 mid、last_seen 是今天。\n所级：按 unit_name 分组，每个台区一句（组里多条就数条数）；\n县级：按 county_name 分组，每个县一句；\n市级：全部合成一句。", "fields": "object_name 对象名、unit_name 归属所、county_name 归属县、tier 档位（high / mid / low）、value 当前值配 value_unit 读（% 表示百分数）、reliable 数据是否可靠（0 不发）、status 问题还在不在。", "phrase": "不超过 30 字，只放一个数字。\n\n所级：{台区名}线损率 {一位小数}%\n县级：本县 {n} 个台区线损超线\n市级：全市 {n} 个台区线损超线\n\n不要写：样本总数、阈值、档位英文（high / mid）、一串明细。\n例：白鹤台区线损率 5.2%", "source": "结果表，按文档名读：doc_name = 台区线损超线；只要 status=open、last_seen 是今天。\n要用到的列：object_name 对象名、unit_name 归属所、county_name 归属县、tier 档位、value 当前值、value_unit 单位。\n最多 200 条，超过就翻页接着读，读完为止。", "delivery": "用 send 工具，一层一句话调一次：\nitem_ids 这几条结果的 id（第一个当成最差那条）\nlevel station / county / city\nscope_name 所名 或 县名 或 全市\nrecipient_login 查到的登录名；message 第五节的句子；reason 写为什么发他\n\n三层发完调 finish，sent_n 填实际发出条数。"}', 6, 'seed', '2026-11-07 11:15:54.003304+08', '2026-11-07 11:26:24.269318+08', 0) ON CONFLICT DO NOTHING;
