INSERT INTO public.wf_doc VALUES (8, '工单长期未结束', 'detect', '审批', 1, NULL, 'station', NULL, NULL, '{"calc": "天数 = create_time 到今天的天数。", "data": "t_power_ai_work_order：id、work_code、work_name、power_company_name、county_company_name、actual_end_time 实际结束时间、create_time、work_status、total_budget（元）、year、deleted_flag。\n只取：year=今年、deleted_flag=0、actual_end_time 为空。", "goal": "查出哪张工单拖了很久还没结束，一张工单一条结果。\n产出：结果为结束时间为空、创建超过 180 天的工单，带已过天数。", "what": "哪张工单拖了很久还没结束。\n算到工单，一张一条。", "judge": "天数 > 180 报；> 270 为高档，其余中档。", "store": "对象：工单名（带所名）；对象键：工单 id。\n归属所：power_company_name；归属县：county_company_name。\n当前值：已过天数，单位 天。\n阈值 180，档位 high / mid。\n明细三项：工单号、工作状态、预算金额。\n依据两项：实际结束时间、创建时间。"}', 6, 'seed', '2026-11-07 11:15:53.987708+08', '2026-11-07 11:26:24.269318+08', 0) ON CONFLICT DO NOTHING;
